import{_ as a,o as s,c as t,a2 as r}from"./chunks/framework.doxMM-x8.js";const b=JSON.parse('{"title":"外观与语言","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/tutorials/appearance-language","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"tutorials/appearance-language.md","filePath":"tutorials/appearance-language.md"}'),i={name:"tutorials/appearance-language.md"};function l(n,e,c,o,p,h){return s(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="外观与语言" tabindex="-1">外观与语言 <a class="header-anchor" href="#外观与语言" aria-label="Permalink to &quot;外观与语言&quot;">​</a></h1><p>目标：在 Lab Word 切换语言和外观，并确认本机偏好被保留。前提是已按<a href="./../getting-started/quickstart">快速开始</a>启动应用。</p><h2 id="操作与结果" tabindex="-1">操作与结果 <a class="header-anchor" href="#操作与结果" aria-label="Permalink to &quot;操作与结果&quot;">​</a></h2><ol><li>使用页面顶部的语言入口切换简体中文或英文，当前界面与页面标题应同时更新。</li><li>在外观入口选择跟随系统、浅色或深色；跟随系统时，操作系统外观变化会更新页面。</li><li>从左下角账户入口进入设置，也可在外观与语言区修改同样的偏好。</li><li>刷新页面，显式选择应继续保留。窄屏通过导航抽屉访问相应入口。</li></ol><p>偏好保存于当前设备，不修改后端权限或业务数据。不同浏览器不会自动同步；禁用存储或清除站点数据后会回到设备默认值。</p><h2 id="开发与验证" tabindex="-1">开发与验证 <a class="header-anchor" href="#开发与验证" aria-label="Permalink to &quot;开发与验证&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/labworld/blob/e080eb3aca90c0e62358b3c5ecd6f779b2b1104e/packages/views/src/shell/preferences.tsx" target="_blank" rel="noreferrer">Preferences</a>负责状态与存储，<a href="https://github.com/CaiZongyuan/labworld/blob/e080eb3aca90c0e62358b3c5ecd6f779b2b1104e/packages/views/src/shell/settings-view.tsx" target="_blank" rel="noreferrer">Settings</a>提供界面；双语文案在 <a href="https://github.com/CaiZongyuan/labworld/blob/e080eb3aca90c0e62358b3c5ecd6f779b2b1104e/packages/views/src/shell/core-messages.ts" target="_blank" rel="noreferrer">core-messages.ts</a>。共享 token 来自 <code>packages/ui/src/styles.css</code>。</p><p>从仓库根目录验证语言、外观和设置行为：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/settings.test.tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/desktop-preferences.test.tsx</span></span></code></pre></div><p>组件检查验证可观察选择与保存。Electron 桥与真实浏览器的系统外观另在各自旅程核对。文档站的主题和语言由自己的站点控制，切换语言仍停留在同一章节。</p><hr><p>源码版本：<code>e080eb3aca90</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/e080eb3aca90c0e62358b3c5ecd6f779b2b1104e/docs/guides/appearance-language.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>',12)])])}const g=a(i,[["render",l]]);export{b as __pageData,g as default};
